import {receiptTermsPages} from './receipt-terms.js?v=20261029';
// Multi-item PDF renderer. Individual receipt rendering remains unchanged.
export async function multiplePaymentPdf(q){
 const logo=new Image();logo.src=new URL('./assets/logo.jpeg',import.meta.url).href;await logo.decode();
 const pages=[],W=1200,H=1697,crc=n=>q.currency==='USD'?'US$ '+new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100):'₡'+new Intl.NumberFormat('es-CR').format(n/100);let canvas,c,y;
 const text=(s,x,yy,size=24,bold=false,right=false)=>{c.font=`${bold?700:400} ${size}px Arial`;c.fillStyle='#202126';c.textAlign=right?'right':'left';c.fillText(s,x,yy);};
 function page(){canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,W,H);c.fillStyle='#101114';c.fillRect(0,0,W,200);c.drawImage(logo,45,5,190,190);c.font='bold 35px Arial';c.fillStyle='#fff';c.textAlign='right';c.fillText('COMPROBANTE DE PAGO',1130,85);c.font='24px Arial';c.fillText(q.number,1130,130);c.fillStyle='#dd1222';c.fillRect(0,200,W,8);text(q.customerName||'Cliente',70,260,27,true);text('Teléfono: '+q.customerPhone,70,300);text('Fecha: '+new Intl.DateTimeFormat('es-CR').format(new Date(q.issuedAt)),1130,300,23,false,true);y=355;}
 async function finish(){text('Seguimiento: '+q.trackingCode,70,H-105,24,true);text('PITSTOP REPUESTOS · Gracias por tu confianza',70,H-55,21);text('Página '+(pages.length+1),1130,H-55,21,false,true);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.94));pages.push(new Uint8Array(await blob.arrayBuffer()));}
 function wrap(s,width){c.font='24px Arial';let line='',lines=[];for(const word of String(s).split(/\s+/)){for(const ch of (line?' ':'')+word){if(c.measureText(line+ch).width>width){lines.push(line);line='';}line+=ch;}}if(line)lines.push(line);return lines;}
 function headings(){c.fillStyle='#f8e8eb';c.fillRect(70,y-28,1060,48);text('REPUESTO',85,y,21,true);text('TOTAL',760,y,21,true,true);text(q.customPayment?'ABONADO':'ADELANTO 20%',950,y,21,true,true);text('SALDO',1120,y,21,true,true);y+=55;}
 page();headings();for(const item of q.items){const lines=wrap(item.product,465),height=Math.max(80,lines.length*30+28);if(y+height>1330){await finish();page();headings();}lines.forEach((s,i)=>text(s,85,y+i*30));text(crc(item.totalMinor),760,y,23,true,true);text(crc(item.paidMinor),950,y,23,true,true);text(crc(item.balanceMinor),1120,y,23,true,true);y+=height;c.fillStyle='#e2e4e8';c.fillRect(70,y-38,1060,1);}
 if(y+390>1450){await finish();page();}for(const [label,value]of [['Envío GRATIS (0%)',0],['Total de la compra',q.totalMinor],[q.customPayment?'Monto abonado':'Adelanto recibido · 20%',q.paidMinor],['Saldo pendiente',q.balanceMinor]]){text(label,85,y,28,true);text(crc(value),1120,y,30,true,true);y+=65;}text('El saldo se cancela al momento de la entrega personal.',85,y+15,24);text('Llegada estimada: '+q.arrival,85,y+58,24);await finish();pages.push(...await receiptTermsPages(q,logo));return pdf(pages,W,H);
}
export function pdf(pages,width,height){const enc=new TextEncoder(),parts=[],offsets=[0];let size=0;const add=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);size+=b.length;},obj=(n,s)=>{offsets[n]=size;add(`${n} 0 obj\n${s}\nendobj\n`);};add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] /Count ${pages.length} >>`);pages.forEach((entry,i)=>{const bytes=entry.bytes||entry,w=entry.width||width,h=entry.height||height;const p=3+i*3;obj(p,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${p+1} 0 R >> >> /Contents ${p+2} 0 R >>`);offsets[p+1]=size;add(`${p+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length} >>\nstream\n`);add(bytes);add('\nendstream\nendobj\n');const scale=Math.min(595.28/w,841.89/h),pw=w*scale,ph=h*scale;const content=`q ${pw} 0 0 ${ph} ${(595.28-pw)/2} ${841.89-ph} cm /Im0 Do Q\n`;obj(p+2,`<< /Length ${content.length} >>\nstream\n${content}endstream`);});const x=size;add(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(let i=1;i<offsets.length;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`);return new Blob(parts,{type:'application/pdf'});}
